select case when budget >= 3564000 then 'high' when budget >= 1312000 then 'mid' else 'low' end as budget_bucket, round((100 * sum(case when dept_name = 'HR' then 1 else 0 end)) / count(*), 1) as pct_hr, count(*) as department_count from departments where location in ('Chiang Mai', 'Berlin') and dept_name is null group by case when budget >= 3564000 then 'high' when budget >= 1312000 then 'mid' else 'low' end having pct_hr < 38 order by budget_bucket limit 5
